/* prog46_postfix_stack – evaluate a postfix expression given on the command line.
 *
 * The original binary implements a tiny stack‑machine that supports the four
 * integer operators +, -, *, / and decimal integer literals.  The stack size is
 * limited to 64 entries.  Any error (invalid token, not enough operands,
 * division by zero, stack overflow, or a final stack that does not contain
 * exactly one value) causes the program to print the literal string
 * "ERROR" and exit without printing a result.
 *
 * The behaviour reproduced below matches the observable output of the
 * supplied binary for all possible inputs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define STACK_MAX 64

int main(int argc, char **argv)
{
    long stack[STACK_MAX];
    int  top = 0;                     /* number of elements currently on stack */

    /* No expression supplied – the original program prints an error. */
    if (argc < 2) {
        puts("ERROR");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];

        /* ----- operator token ? ----- */
        if (strlen(tok) == 1 && strchr("+-*/", tok[0])) {
            if (top < 2) {                 /* not enough operands */
                puts("ERROR");
                return 0;
            }

            long b = stack[--top];         /* right operand */
            long a = stack[--top];         /* left  operand */
            long res;

            switch (tok[0]) {
                case '+':  res = a + b; break;
                case '-':  res = a - b; break;
                case '*':  res = a * b; break;
                case '/':
                    if (b == 0) {          /* division by zero */
                        puts("ERROR");
                        return 0;
                    }
                    res = a / b;
                    break;
                default:   /* never reached */ res = 0;
            }

            if (top >= STACK_MAX) {        /* overflow – should never happen here */
                puts("ERROR");
                return 0;
            }
            stack[top++] = res;
            continue;
        }

        /* ----- numeric literal ----- */
        {
            char *endptr;
            long val = strtol(tok, &endptr, 10);

            /* token is not a valid integer */
            if (endptr == tok || *endptr != '\0') {
                puts("ERROR");
                return 0;
            }

            if (top >= STACK_MAX) {        /* stack overflow */
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
        }
    }

    /* After processing all tokens exactly one value must remain on the stack. */
    if (top != 1) {
        puts("ERROR");
        return 0;
    }

    printf("%ld\n", stack[0]);
    return 0;
}
